/** Lowest current package price for a park, read from tours.ts so copy never drifts from pricing. */
const from = (jungle: string) => {
  const prices = tours.filter((tour) => tour.jungle === jungle).map((tour) => tour.price);
  return prices.length ? inr(Math.min(...prices)) : 'on request';
};
const fromLine = (jungle: string, label: string) => `<a href="/tours/${jungle}/">${label} packages from ${from(jungle)} per person</a>`;

const priceRow = (jungle: string, label: string, note: string) => [`<a href="/tours/${jungle}/">${label}</a>`, from(jungle), note];

